changeSet.sql:
INSERT INTO parser (name, description, dataset_name, list_type, website_url, plugin_id, plugin_url, data_source_type, parser_kind, source_location, parameters, refresh_hours, retention_months, licence, attribution, notes, enabled, created_at) VALUES ('PEP France – Membres du Gouvernement', 'Premier ministre, ministres, ministres délégués et secrétaires d''État en fonction, et anciens membres récents, d''après les déclarations publiées par la HATVP (catégorie FR-a)', 'fr_pep_government', 'PEP', 'https://www.hatvp.fr/open-data/', 'fr-pep-government', 'D:/test parser 2/plugins/swiftcheck-aml-fr-pep-government-0.0.1-SNAPSHOT.jar', 'PLUGIN_MANAGED', 'DECLARATION_REGISTER', NULL, '{"listUrl": "https://www.hatvp.fr/livraison/opendata/liste.csv", "declarationsUrl": "https://www.hatvp.fr/livraison/dossiers/", "delayMs": "300", "monthsAfterEnd": "12"}', 24, 12, 'Licence Ouverte / Open Licence (Etalab 2.0)', 'Haute Autorité pour la transparence de la vie publique, www.hatvp.fr (open data)', 'Un nouveau membre n''apparaît qu''après le dépôt de sa première déclaration (dans les deux mois de sa nomination) ; date de naissance et dates de fonction après sa publication. info.gouv.fr n''est pas utilisé : il refuse l''accès aux robots (HTTP 403).', TRUE, NOW());
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former) SELECT f.id, p.id, 'COMPLETE', TRUE FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'FR-a' AND f.label = 'Premier ministre, ministre ou secrétaire d''État' AND p.dataset_name = 'fr_pep_government';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former) SELECT f.id, p.id, 'PARTIAL', TRUE FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'FR-a' AND f.label = 'Ancien membre du Gouvernement' AND p.dataset_name = 'fr_pep_government';
